set -e; runuser -u postgres -- psql -v ON_ERROR_STOP=1 -d infraset <<'SQL'
DO $do$
DECLARE r record;
BEGIN
  FOR r IN SELECT rolname FROM pg_roles WHERE rolname LIKE 'v-token-infraset-%' LOOP
    EXECUTE format('DROP OWNED BY %I', r.rolname);
    EXECUTE format('DROP ROLE IF EXISTS %I', r.rolname);
  END LOOP;
END
$do$;
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'infraset_app_dml') THEN
    CREATE ROLE infraset_app_dml NOLOGIN;
  END IF;
END
$do$;
ALTER ROLE infraset_app_dml NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT;
GRANT infraset_app_dml TO vault_admin WITH ADMIN OPTION;
GRANT CONNECT ON DATABASE infraset TO infraset_app_dml;
GRANT USAGE ON SCHEMA public TO infraset_app_dml;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.credential_probe TO infraset_app_dml;
GRANT USAGE, SELECT ON SEQUENCE public.credential_probe_id_seq TO infraset_app_dml;
REVOKE ALL ON TABLE public.credential_probe FROM PUBLIC;
REVOKE ALL ON SEQUENCE public.credential_probe_id_seq FROM PUBLIC;
SQL
